/* ===== Sydney Paintmasters footer (matches live site). Only change vs live: LinkedIn replaced with YouTube. =====
   Font family: Fustat (the live site's own font).
   Background colour: #1c293f (the live site navy, from the live CSS extraction).
   Text colours below are set to sit on that navy and match the live footer look. */
*{box-sizing:border-box}
body{margin:0;background:#141d2c;font-family:'Fustat',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif}
.spm-footer{background:#1c293f;color:#9ba7be;font-family:'Fustat',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;font-size:16px;line-height:1.6}
.spm-footer .spm-container{max-width:1280px;margin:0 auto;padding:0 24px}
.spm-foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr 1.35fr;gap:40px;padding:66px 0 40px}
.spm-footer a{text-decoration:none}
/* brand column */
.spm-logo{height:104px;width:auto;display:block;margin:0 0 22px;filter:brightness(0) invert(1)}
.spm-brand p{margin:0 0 24px;color:#97a1b4;max-width:32ch}
.spm-social{display:flex;gap:14px}
.spm-social a{width:46px;height:46px;border-radius:12px;background:rgba(255,255,255,.07);display:flex;align-items:center;justify-content:center;color:#fff;font-size:1.15rem;transition:background .15s}
.spm-social a:hover{background:#016edc}
/* link columns */
.spm-col h4{color:#fff;font-size:1.2rem;font-weight:700;margin:0 0 22px}
.spm-col ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}
.spm-col a{color:#9ba7be}
.spm-col a:hover{color:#fff}
/* contact column */
.spm-contact ul{gap:20px}
.spm-contact li{display:flex;gap:12px;align-items:flex-start;color:#cbd2de}
.spm-contact li i{color:#ffa800;font-size:1rem;margin-top:4px;width:18px;text-align:center;flex:none}
.spm-contact a{color:#cbd2de}
.spm-contact a:hover{color:#fff}
/* bottom bar */
.spm-foot-bottom{border-top:1px solid rgba(255,255,255,.11);padding:26px 0 34px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;font-size:.95rem;color:#8a94a8}
.spm-foot-bottom a{color:#5a9be6}
.spm-foot-bottom a:hover{text-decoration:underline}
.spm-foot-bottom .sep{color:#5a9be6;margin:0 6px}
@media(max-width:960px){
  .spm-foot-grid{grid-template-columns:1fr 1fr;gap:36px 28px;padding-top:52px}
}
@media(max-width:560px){
  .spm-foot-grid{grid-template-columns:1fr}
  .spm-foot-bottom{flex-direction:column;align-items:flex-start;gap:10px}
}

:root{
  --max:1200px;
  --font:"Fustat",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0}
body{font-family:var(--font);background:#f5f5f5}

/* demo filler so the footer reads as sitting at the base of a page */
.demo-note{max-width:var(--max);margin:0 auto;padding:56px 24px 40px;color:#5b6470;font-size:14px;text-align:center}

/* ---- LIVE FOOTER STYLES (verbatim from production lfoot rules) ---- */
.lfoot{color:#9db0cc;background:#0c1a2e;font-size:.9rem;line-height:1.65;font-family:var(--font)}
.lfoot-wrap{max-width:var(--max);margin:0 auto;padding:78px 24px 26px}
.lfoot-grid{grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;display:grid}
.lfoot-h{color:#fff;margin-bottom:18px;font-size:1.05rem;font-weight:700;margin-top:0}
.lfoot-about{margin-bottom:12px}
.lfoot-meta{margin:0}
.lfoot-meta a,.lfoot-list a{color:#9db0cc;text-decoration:none}
.lfoot-meta a:hover,.lfoot-list a:hover{color:#fff}
.lfoot-list{gap:10px;margin:0;padding:0;list-style:none;display:grid}
.lfoot-subs{columns:2}
.lfoot-bottom{color:#7d90ad;border-top:1px solid #ffffff1a;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-top:30px;padding-top:20px;font-size:.82rem;display:flex}

@media (max-width:820px){.lfoot-grid{grid-template-columns:1fr 1fr}}
@media (max-width:520px){.lfoot-grid{grid-template-columns:1fr}.lfoot-subs{columns:1}}

